import type { MsgPack } from '../msgpack';
import type { CborUintArray } from '../cbor/types';
import type { Brand } from '@jsonjoy.com/util/lib/types';
export type base_string<T extends UintArray = UintArray> = Brand<string, T, 'base_string'>;
export type binary_string<T extends UintArray = UintArray> = Brand<`data:application/octet-stream;base,${base_string<T>}`, T, 'binary_string'>;
export type cbor_string<T = unknown> = Brand<`data:application/cbor;base,${base_string<CborUintArray<T>>}`, T, 'cbor_string'>;
export type msgpack_string<T = unknown> = Brand<`data:application/msgpack;base,${base_string<MsgPack<T>>}`, T, 'msgpack_string'>;
